using Microsoft.ApplicationInsights;
using Microsoft.ApplicationInsights.DataContracts;

public class CheckoutService
{
    private readonly TelemetryClient _telemetry;

    public CheckoutService(TelemetryClient telemetry) => _telemetry = telemetry;

    public async Task ProcessAsync(Order order)
    {
        var stopwatch = System.Diagnostics.Stopwatch.StartNew();

        _telemetry.TrackEvent("CheckoutStarted", new Dictionary<string, string>
        {
            ["OrderId"] = order.Id,
            ["Region"] = order.Region
        });

        // business logic
        await SaveOrderAsync(order);

        stopwatch.Stop();
        _telemetry.GetMetric("CheckoutDurationMs").TrackValue(stopwatch.ElapsedMilliseconds);
        _telemetry.TrackEvent("CheckoutCompleted", new Dictionary<string, string>
        {
            ["OrderId"] = order.Id
        });
    }
}

public class PostsController : ControllerBase
{
    private readonly ILogger<PostsController> _logger;
    private readonly BlogContext _db;

    public PostsController(ILogger<PostsController> logger, BlogContext db)
    {
        _logger = logger;
        _db = db;
    }

    [HttpGet("{id}")]
    public async Task<ActionResult<Post>> Get(int id)
    {
        _logger.LogInformation("Fetching post {PostId} from Azure SQL", id);
        var post = await _db.Posts.FindAsync(id);

        if (post is null)
        {
            _logger.LogWarning("Post {PostId} not found", id);
            return NotFound();
        }

        return Ok(post);
    }
}
